'use strict';
/* ============================================================================
   treemodel.js — the flora used on worlds that have trees.

   Baked from a glTF the same way as the ship, and embedded as base64 so the
   game still runs from file://.

   The source turned out to be three trees standing in a row, not one, sharing a
   bark mesh and a leaf/branch mesh.  They are split back apart here on triangle
   centroids and kept as three variants of one vertex buffer, each pivoted at
   its own trunk with Y = 0 at the ground; a common scale preserves their
   relative sizes.  Instancing then picks a variant per tree, so a stand of
   trees is not one silhouette repeated.

   Bark tiles its UVs (they run -3.5 to 12), so it cannot share an atlas and
   keeps its own repeating texture; leaf and branch both sit inside [0,1] and
   are packed into one alpha-masked atlas.  Six index ranges over one buffer —
   three variants times two materials — rather than a draw per tree.

   UVs are stored with t flipped, because the runtime uploads every texture with
   UNPACK_FLIP_Y_WEBGL and glTF counts v the other way.

   The source animation is a morph-target wind bake.  It is dropped here: the
   runtime sways the canopy procedurally in the vertex shader instead, keyed to
   world position, which costs nothing and gives every instance its own phase
   rather than every tree in the forest moving as one.
   ============================================================================ */

const TREE_MODEL = {
  vertexCount: 25952,
  indexCount: 56013,
  /* Tallest variant, in metres — the sway falls off against this. */
  height: 11.000,
  bounds: { lo: [-6.662, 0.000, -6.281], hi: [6.059, 11.000, 6.329] },
  posBias: [-0.30146, 5.50000, 0.02396],
  posScale: [6.36049, 5.50000, 6.30533],
  uvBias: [-3.499098, -10.951242],
  uvScale: [8.126268, 11.951242],

  /* variants[v][m] = [indexStart, indexCount]; m: 0 = bark, 1 = foliage atlas */
  variants: [[[0, 3336], [3336, 21990]], [[25326, 3291], [28617, 14694]], [[43311, 2379], [45690, 10323]]],
  alphaCutoff: 0.407,
  /* Texel dimensions, so the shader can relax the alpha test as the mip chain
     thins the mask out — without it a canopy goes bald with distance. */
  barkSize: [512, 512],
  atlasSize: [1280, 1024],

  pos: '',
  nrm: '',
  uv:  '',
  idx: '',

  bark: 'data:image/jpeg;base64,',
  atlas: 'data:image/webp;base64,'
};
